import{_ as e,o as t,c as o,a4 as n}from"./chunks/framework.2-Vke5-n.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"Markdown<wbr>設計ドキュメント<wbr>規約","tagline":"Markdown Design Document Guidelines","actions":[{"theme":"brand","text":"Markdown設計ドキュメント規約","link":"./markdown_design_document.md"},{"theme":"alt","text":"サンプルプロジェクト","link":"./sample/"}]}},"headers":[],"relativePath":"documents/forMarkdown/index.md","filePath":"documents/forMarkdown/index.md"}'),r={name:"documents/forMarkdown/index.md"};function i(l,a,d,s,p,c){return t(),o("div",null,[...a[0]||(a[0]=[n('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>Markdown ベースの設計ドキュメントの規約をまとめる。</p><p>システム開発にて利用する設計ドキュメントを Markdown ベースにすることで、コーディングと同じ慣れたツールを用いて Git によるバージョン管理・レビュープロセス・CI/CD などに自動化（静的解析・自動生成）を行いやすくし、ドキュメントを陳腐化させず、俊敏な設計開発を目指す。</p><p>Markdown に限った話では無いが、どういった内容を設計書に記載すべきかは悩むポイントは多い。</p><p>本ガイドラインでは、アプリケーションの種別ごとに記載すべき内容とそれをどのような Markdown の構造で記載するかを規約化し、各チームで悩む余地を減らし、注力すべきことに集中できる環境を提供することを目的とする。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署 / プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="前提" tabindex="-1">前提 <a class="header-anchor" href="#前提" aria-label="Permalink to &quot;前提&quot;">​</a></h2><p>本ガイドラインは以下の前提で作成されている。</p><ul><li>チーム/プロジェクトが 3 ～ 10 名程度の規模</li><li>Git（GitHub, GitLab）で管理され、コードと設計書が同一リポジトリで管理される</li><li>システム開発で必要なアプリケーション開発</li></ul><h2 id="本ガイドラインで紹介する設計ドキュメントの位置付け" tabindex="-1">本ガイドラインで紹介する設計ドキュメントの位置付け <a class="header-anchor" href="#本ガイドラインで紹介する設計ドキュメントの位置付け" aria-label="Permalink to &quot;本ガイドラインで紹介する設計ドキュメントの位置付け&quot;">​</a></h2><p>設計ドキュメントは様々な前提条件 / 制約 / 経緯で作成され、Excel / Word / パワーポイントなどのファイル形式で作成することが多い。</p><p>本ガイドラインはそれらを否定するものではなく、様々な利害関係者の要求に応え洗練され続けた上記の設計ドキュメントのテンプレートには、強く敬意を表する。</p><p>一方で、設計ドキュメントを精緻に管理していく優先度より、プロダクト開発の効率とビジネスピードをより重視する場合もある。それらの開発チームでは設計ドキュメントが存在さえない、あっても設計書が実装と乖離しているなどの問題が世間で課題提起されることも多い。</p><p>本ガイドラインでは、後者のプロダクト開発の効率性を重視し、設計ドキュメントが開発以外の観点から求められない場合において、必要最低限必要だと思われるレベルの記載のサンプルを提供する。</p><p>また、設計ドキュメントのファイル形式に制約は無いという前提に立つため、設計ドキュメントの陳腐化を防ぐのに有効だと思われる、テキストベース（Markdown）でGit管理するという思想を採用する。</p><p>本ガイドラインで紹介した各設計ドキュメントの記載内容を参考にしつつ、各開発チームにおいて必要な情報を追加 / 削除して利用するという、テンプレートとしての利用を想定する。</p><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、武田大輝、宮崎将太、澁川喜規、合田飛、山本竜玄、清水雄一郎、保谷安胤、洞内惇、橋本竜我</li></ul><div class="next-page-nav"><p>次のページ: <a href="./markdown_design_document.html">Markdown設計ドキュメント規約</a></p></div>',20)])])}const m=e(r,[["render",i]]);export{h as __pageData,m as default};
